export const editCount=e=>['species','moves','items','trainers','encounters'].reduce((n,k)=>n+Object.keys(e?.[k]||{}).length,0)+(e?.sprites?.length||0)+(e?.forms?.length||0);
export function editsFor(project,hash,create=false){if(create){project.romEdits??={};project.romEdits[hash]??={species:{},moves:{},items:{},trainers:{},encounters:{},sprites:[]};}return project.romEdits?.[hash];}
export function validateGameEdits(project){if(project.romEdits===undefined)return;if(!project.romEdits||Array.isArray(project.romEdits)||Object.keys(project.romEdits).length>16)throw Error('The ROM edit collection is invalid.');if(JSON.stringify(project.romEdits).length>48e6)throw Error('This project has too much sprite/game data. Split it into smaller projects.');for(const[hash,e]of Object.entries(project.romEdits)){if(!/^[a-f0-9]{64}$/.test(hash)||!e||editCount(e)>4096)throw Error('ROM edits need a valid source digest.');for(const k of['species','moves','items','trainers','encounters'])if(e[k]!==undefined&&(!e[k]||Array.isArray(e[k])||typeof e[k]!=='object'))throw Error('A ROM data collection is invalid.');if(e.sprites!==undefined&&(!Array.isArray(e.sprites)||e.sprites.length>4096))throw Error('The sprite edit collection is invalid.');if(e.forms!==undefined&&(!Array.isArray(e.forms)||e.forms.length>256||e.forms.some(f=>!f||!Number.isInteger(f.slot)||f.slot<1||f.slot>8191||!Number.isInteger(f.parent)||f.parent<1||f.parent>8191||typeof f.groupId!=='string'||typeof f.name!=='string'||f.name.length>12)))throw Error('The native form collection is invalid.');for(const s of e.sprites||[]){if(!['mon','trainer','icon','overworld','npc'].includes(s.kind)||!Number.isInteger(s.id)||s.id<0||s.id>8191||s.frame!==undefined&&(!Number.isInteger(s.frame)||s.frame<0||s.frame>63)||s.pixels!==undefined&&(!Array.isArray(s.pixels)||(s.pixels.length<64||s.pixels.length>16384||s.pixels.length%64!==0)||s.pixels.some(i=>!Number.isInteger(i)||i<0||i>15))||s.palette!==undefined&&(!Array.isArray(s.palette)||s.palette.length!==16||s.palette.some(c=>!/^#[a-f0-9]{6}$/i.test(c))))throw Error('A saved sprite edit is invalid.');}}}
